//! Exact authored semantic-surface inventory for smusni v0.
//!
//! Every row below is an independent reviewed coordinate. The build-time AST
//! scan, this inventory, and the generated candidate registry must be equal as
//! sets; no wildcard assigns a disposition to a future model member.

#[allow(unused_imports)]
use bityzba::{ensures, new, requires};

use super::model::{
    Disposition, EntryKind, FailureClass, InventoryEntry, Presence, RenderFieldInventory, Surface,
    SurfaceCategory, Witness, WitnessData, WitnessExpect, WitnessExpectData,
};

#[requires(!surface.is_empty() && !member.is_empty())]
#[requires(qualifier.is_none_or(|value| !value.is_empty()))]
#[ensures(ret.surface.name == surface && ret.field == member)]
fn entry(
    category: SurfaceCategory,
    surface: &'static str,
    kind: EntryKind,
    member: &'static str,
    qualifier: Option<&'static str>,
    presence: Presence,
    witness: Witness,
    disposition: Disposition,
) -> InventoryEntry {
    InventoryEntry::new(
        Surface::new(category, surface),
        member,
        kind,
        presence,
        witness,
        qualifier,
        disposition,
    )
}

